return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", "GATEWAY_UNAUTHORIZED"),
                                new JProperty("message", "Missing or invalid access token (rejected by the API gateway)"),
                                new JProperty("details", new JObject(
                                    new JProperty("reason", context.LastError.Message),
                                    new JProperty("requestId", context.RequestId.ToString())
                                ))
                            ))
                        ).ToString();
                    }
